1	import { afterAll, beforeAll, describe, expect, it } from "vitest";
2	import { isNavigable, seaMap } from "@pirate-sea-race/content";
3	import { ShopMessageType } from "@pirate-sea-race/protocol";
4	import { startGameServer, type MatchRoom, type RunningGameServer } from "@pirate-sea-race/server";
5	import { defaultSimulationConfig, drinkTonic, hashState, step, type MatchState } from "@pirate-sea-race/simulation";
6	import { checkLedger, findPlayer, objectiveRules } from "@pirate-sea-race/simulation/objectives";
7	import { AHEAD, HeadlessClient, sleep } from "@pirate-sea-race/test-tools";
8	import { placePair, tuned } from "./rubbingsSetup.js";
9	import { dockFor, EAST, HOLD_E, HUB_X, NORTH, OPEN_ROW, openWater, playersAt, roomOf, startThroughLobby, tracker, until, WEST, type Seat } from "./seaDuelSetup.js";
10	
11	/**
12	 * §11's economy through the real room: the supply crates at sea, the dockside shop's sail tonic (and its rumor, the
13	 * journal's purchase), and the tonic's speed. Players drive it as a browser does: they sail with the helm, moor with E,
14	 * send `buy-tonic` and `use-tonic` with their request ids. Every player starts with the rules' 50 gold; a tonic costs 30,
15	 * a crate pays 25. The rooms check `checkLedger` (the gold identity among it) and their own invariant after every world
16	 * tick, and that the ledger refused nothing the room asked (`tracker`). Cases that need one exact tick hold the clock
17	 * with the room's test hooks (`pauseAfterTick`, `stepWorldTicks`).
18	 */
19	let server: RunningGameServer;
20	let endpoint: string;
21	
22	beforeAll(async () => {
23	  server = await startGameServer({
24	    port: 0,
25	    host: "127.0.0.1",
26	    handleSignals: false,
27	    testPlacement: true,
28	    matchTuning: tuned({ objectives: { ...objectiveRules, collectTicks: 20, cacheClaimTicks: 20 }, testHooks: true }),
29	  });
30	  endpoint = `http://127.0.0.1:${server.port}`;
31	});
32	
33	afterAll(async () => {
34	  await server.close();
35	});
36	
37	const PRICE = objectiveRules.tonicPrice;
38	const CRATE_GOLD = objectiveRules.supplyCacheGold;
39	const TONIC_TICKS = objectiveRules.tonicTicks;
40	const START = objectiveRules.startingGold;
41	/** Somewhere on the open row south of the hub, out of every crate's sight. */
42	const ROW: Seat = { tileX: HUB_X - 6, tileY: OPEN_ROW, heading: EAST };
43	
44	const goldOf = (room: MatchRoom, id: string) => findPlayer(room.ledgerState, id)!.gold;
45	const tonicsOf = (room: MatchRoom, id: string) => findPlayer(room.ledgerState, id)!.tonics;
46	const supplyGrants = (room: MatchRoom) => room.ledgerState.grants.filter((grant) => grant.reason === "supply-cache");
47	
48	/** A crate's site and a seat three tiles west of it, facing it along clear water. */
49	function crateSeat(room: MatchRoom, index: number): { crate: { id: string; x: number; y: number; tileX: number; tileY: number }; seat: Seat } {
50	  const crate = room.crateSites[index]!;
51	  const seat = { tileX: crate.tileX - 3, tileY: crate.tileY, heading: EAST };
52	  expect(openWater(seat, { ...crate, heading: EAST })).toBe(true);
53	  return { crate, seat };
54	}
55	
56	/** Sails a ship over a crate from three tiles west of it until it has the crate's gold. */
57	async function takeCrate(client: HeadlessClient, index: number): Promise<void> {
58	  const room = roomOf(client);
59	  const before = goldOf(room, client.sessionId);
60	  await client.placeShip(endpoint, crateSeat(room, index).seat);
61	  await client.holdUntil(AHEAD, () => goldOf(room, client.sessionId) === before + CRATE_GOLD, 5000);
62	}
63	
64	/** Places a ship on a dock's tile and holds E until it is moored there. */
65	async function moor(client: HeadlessClient, dock: { id: number; tileX: number; tileY: number } = dockFor("sun")): Promise<void> {
66	  await client.placeShip(endpoint, { tileX: dock.tileX, tileY: dock.tileY, heading: 0 });
67	  await client.holdUntil(HOLD_E, () => client.ship()?.dock === dock.id, 5000);
68	}
69	
70	/** Sends a tonic purchase (a fresh id unless given) and resolves with its answer (the latest, for a retried id). */
71	async function buy(client: HeadlessClient, requestId?: string) {
72	  const id = client.buyTonic(requestId);
73	  const before = client.tonicPurchaseAnswers(id).length;
74	  await client.waitFor(() => client.tonicPurchaseAnswers(id).length > before, 3000);
75	  return client.tonicPurchaseAnswers(id).at(-1)!;
76	}
77	
78	/** Sends a drink request (a fresh id unless given) and resolves with its answer. */
79	async function drink(client: HeadlessClient, requestId?: string) {
80	  const id = client.useTonic(requestId);
81	  const before = client.tonicUseAnswers(id).length;
82	  await client.waitFor(() => client.tonicUseAnswers(id).length > before, 3000);
83	  return client.tonicUseAnswers(id).at(-1)!;
84	}
85	
86	/** Holds the room's clock after the current world tick. */
87	async function pause(room: MatchRoom): Promise<void> {
88	  room.pauseAfterTick(room.matchState.worldTick);
89	  await until(() => room.worldPaused, 2000, "the pause");
90	}
91	
92	describe.concurrent("supply crates (§3, §11)", () => {
93	  it("pays the first ship to touch a crate 25 gold once; the crate vanishes for everyone in sight, and a second ship gets nothing", async ({ onTestFinished }) => {
94	    const track = tracker(onTestFinished);
95	    const [first, second] = (await playersAt(endpoint, [ROW, { ...ROW, tileX: ROW.tileX + 4 }], track)) as [HeadlessClient, HeadlessClient];
96	    const room = roomOf(first);
97	    const { crate, seat } = crateSeat(room, 0);
98	    // The second ship waits four tiles south of the crate, in sight of it.
99	    const below: Seat = { tileX: crate.tileX, tileY: crate.tileY + 4, heading: NORTH };
100	    await first.placeShip(endpoint, seat);
101	    await second.placeShip(endpoint, below);
102	    for (const client of [first, second]) await client.waitFor(() => client.crates().some((each) => each.id === crate.id));
103	    expect(first.crates().find((each) => each.id === crate.id)).toEqual({ id: crate.id, x: crate.x, y: crate.y });
104	    await first.holdUntil(AHEAD, () => first.gold() === START + CRATE_GOLD, 5000);
105	    expect(supplyGrants(room)).toEqual([expect.objectContaining({ sourceKey: crate.id, playerId: first.sessionId, amount: CRATE_GOLD })]);
106	    // Gone for both, the one who took it and the one watching.
107	    for (const client of [first, second]) await client.waitFor(() => !client.crates().some((each) => each.id === crate.id));
108	    // The second ship sails right over where it floated: nothing.
109	    await second.holdUntil(AHEAD, () => (second.ship()?.y ?? Infinity) < crate.y - 200 || second.ship()?.speed === 0, 5000);
110	    await sleep(200);
111	    expect(goldOf(room, second.sessionId)).toBe(START);
112	    expect(goldOf(room, first.sessionId)).toBe(START + CRATE_GOLD);
113	    expect(supplyGrants(room)).toHaveLength(1);
114	    expect(checkLedger(room.ledgerState)).toEqual([]);
115	  }, 30_000);
116	
117	  it("gives a crate two ships touch on the same tick to the lower player id, whatever the join order", async ({ onTestFinished }) => {
118	    const track = tracker(onTestFinished);
119	    // Players join until one has a lower id than someone who joined before them (each join has at least even odds);
120	    // that pair plays, the earlier one first in join order, and the rest leave the lobby.
121	    const present = [await HeadlessClient.create(endpoint)];
122	    track(present[0]!);
123	    let pair: [HeadlessClient, HeadlessClient] | undefined;
124	    while (pair === undefined) {
125	      expect(present.length).toBeLessThan(6);
126	      const next = await HeadlessClient.join(endpoint, present[0]!.code);
127	      track(next);
128	      const earlier = present.find((client) => next.sessionId < client.sessionId);
129	      if (earlier !== undefined) pair = [earlier, next];
130	      else present.push(next);
131	    }
132	    for (const client of present) if (client !== pair[0]) await client.leave();
133	    const [host, guest] = pair;
134	    await host.waitFor(() => host.playerCount === 2);
135	    await host.waitFor(() => host.seat !== 0 && host.hostSeat === host.seat);
136	    await startThroughLobby(endpoint, [host, guest]);
137	    const room = roomOf(host);
138	    expect(room.matchState.ships.map((ship) => ship.id)).toEqual([host.sessionId, guest.sessionId]);
139	    expect(guest.sessionId < host.sessionId).toBe(true);
140	    const { crate } = crateSeat(room, 1);
141	    await pause(room);
142	    // Both ships put at rest on the crate's tile while the clock is held: both touch it on the next tick.
143	    for (const client of [host, guest]) await client.placeShip(endpoint, { tileX: crate.tileX, tileY: crate.tileY, heading: EAST });
144	    expect(supplyGrants(room)).toEqual([]);
145	    const tick = room.matchState.worldTick + 1;
146	    room.stepWorldTicks(1);
147	    room.resumeWorld();
148	    expect(supplyGrants(room)).toEqual([{ reason: "supply-cache", sourceKey: crate.id, playerId: guest.sessionId, amount: CRATE_GOLD, tick }]);
149	    expect(goldOf(room, guest.sessionId)).toBe(START + CRATE_GOLD);
150	    expect(goldOf(room, host.sessionId)).toBe(START);
151	    expect(checkLedger(room.ledgerState)).toEqual([]);
152	  }, 30_000);
153	
154	  it("hides the crates in sight from a player in a duel, as every other marker", async ({ onTestFinished }) => {
155	    const track = tracker(onTestFinished);
156	    const [attacker, defender] = (await playersAt(endpoint, [ROW, { ...ROW, tileX: ROW.tileX + 4 }], track, { clients: [{}, { autoReady: false }] })) as [HeadlessClient, HeadlessClient];
157	    const room = roomOf(attacker);
158	    const crate = room.crateSites[0]!;
159	    // Both two rows south of the crate, in grapple range, the attacker facing the defender; neither touches it.
160	    const west: Seat = { tileX: crate.tileX - 4, tileY: crate.tileY + 2, heading: EAST };
161	    const east: Seat = { tileX: crate.tileX, tileY: crate.tileY + 2, heading: WEST };
162	    expect(openWater(west, east)).toBe(true);
163	    await attacker.placeShip(endpoint, west);
164	    await defender.placeShip(endpoint, east);
165	    for (const client of [attacker, defender]) await client.waitFor(() => client.crates().some((each) => each.id === crate.id));
166	    attacker.tapGrapple();
167	    for (const client of [attacker, defender]) await client.waitFor(() => client.status()?.mode === "duel", 5000);
168	    for (const client of [attacker, defender]) await client.waitFor(() => client.crates().length === 0);
169	    expect(supplyGrants(room)).toEqual([]);
170	  }, 30_000);
171	
172	  it("shows crates only in sight, and a player's gold, tonics and purchases only to that player", async ({ onTestFinished }) => {
173	    const track = tracker(onTestFinished);
174	    const [buyer, stranger] = (await playersAt(endpoint, [ROW, { ...ROW, tileX: ROW.tileX + 4 }], track)) as [HeadlessClient, HeadlessClient];
175	    const room = roomOf(buyer);
176	    // The stranger stays on the open row, more than the sight radius from every crate: it never decodes one.
177	    const strangerCrates = new Set<string>();
178	    stranger.room.onStateChange(() => {
179	      for (const crate of stranger.crates()) strangerCrates.add(crate.id);
180	    });
181	    for (const crate of room.crateSites) {
182	      const [dx, dy] = [crate.x - stranger.ship()!.x, crate.y - stranger.ship()!.y];
183	      expect(dx * dx + dy * dy).toBeGreaterThan(defaultSimulationConfig.sightRadius ** 2);
184	    }
185	    expect(buyer.crates()).toEqual([]);
186	    await takeCrate(buyer, 2);
187	    await moor(buyer);
188	    expect(await buy(buyer)).toMatchObject({ outcome: "bought" });
189	    expect(await drink(buyer)).toMatchObject({ outcome: "refused", reason: "not-at-sea" });
190	    await sleep(300);
191	    expect(strangerCrates).toEqual(new Set());
192	    // The stranger's state holds its own status only, and no message of the buyer's reached it.
193	    expect([...(stranger.room.state.status?.keys() ?? [])]).toEqual([stranger.sessionId]);
194	    expect(stranger.messages.map((each) => each.type)).not.toContain(ShopMessageType.TonicPurchase);
195	    expect(stranger.messages.map((each) => each.type)).not.toContain(ShopMessageType.TonicUsed);
196	    expect(stranger.tonicPurchases).toEqual([]);
197	    expect(stranger.shopView()).toMatchObject({ gold: START, tonics: 0 });
198	    // The buyer's own status says it all.
199	    await buyer.waitFor(() => buyer.shopView()?.tonics === 1);
200	    expect(buyer.shopView()).toMatchObject({ gold: START + CRATE_GOLD - PRICE, tonics: 1, tonicUntil: 0, maxSpeed: 39 });
201	    expect([...(buyer.room.state.status?.keys() ?? [])]).toEqual([buyer.sessionId]);
202	  }, 30_000);
203	});
204	
205	describe.concurrent("the dockside shop (§11)", () => {
206	  it("sells a tonic for 30 gold at a dock, replays a retried id without charging again, and refuses a third tonic (tonic-limit) at no cost", async ({ onTestFinished }) => {
207	    const track = tracker(onTestFinished);
208	    const [buyer] = (await playersAt(endpoint, [ROW], track)) as [HeadlessClient];
209	    const room = roomOf(buyer);
210	    // Two crates first: 100 gold, enough for three tonics.
211	    await takeCrate(buyer, 0);
212	    await takeCrate(buyer, 1);
213	    await moor(buyer);
214	    expect(await buy(buyer, "a")).toEqual({ requestId: "a", outcome: "bought", price: PRICE, tonics: 1, replayed: false });
215	    expect(goldOf(room, buyer.sessionId)).toBe(100 - PRICE);
216	    expect(tonicsOf(room, buyer.sessionId)).toBe(1);
217	    await buyer.waitFor(() => buyer.shopView()?.tonics === 1 && buyer.gold() === 100 - PRICE);
218	    // The same id again: the same answer, replayed, nothing charged.
219	    expect(await buy(buyer, "a")).toEqual({ requestId: "a", outcome: "bought", price: PRICE, tonics: 1, replayed: true });
220	    expect(goldOf(room, buyer.sessionId)).toBe(100 - PRICE);
221	    expect(await buy(buyer, "b")).toMatchObject({ outcome: "bought", tonics: 2 });
222	    // A third: refused, gold and tonics unchanged; retried, the refusal replays.
223	    expect(await buy(buyer, "c")).toEqual({ requestId: "c", outcome: "refused", reason: "tonic-limit", replayed: false });
224	    expect(await buy(buyer, "c")).toEqual({ requestId: "c", outcome: "refused", reason: "tonic-limit", replayed: true });
225	    expect(goldOf(room, buyer.sessionId)).toBe(100 - 2 * PRICE);
226	    expect(tonicsOf(room, buyer.sessionId)).toBe(2);
227	    expect(room.ledgerState.goldSpent).toBe(2 * PRICE);
228	    expect(room.ledgerState.requests.map((request) => request.requestId)).toEqual(["tonic:a", "tonic:b", "tonic:c"]);
229	  }, 30_000);
230	
231	  it("refuses too little gold at no cost, and a purchase after casting off (not-at-dock), decided on the tick it is processed", async ({ onTestFinished }) => {
232	    const track = tracker(onTestFinished);
233	    const [buyer] = (await playersAt(endpoint, [ROW], track)) as [HeadlessClient];
234	    const room = roomOf(buyer);
235	    await moor(buyer);
236	    expect(await buy(buyer)).toMatchObject({ outcome: "bought" });
237	    expect(await buy(buyer, "short")).toEqual({ requestId: "short", outcome: "refused", reason: "insufficient-gold", replayed: false });
238	    expect(goldOf(room, buyer.sessionId)).toBe(START - PRICE);
239	    // Sent while moored, decided after the ship cast off: the tick that processes it decides.
240	    await pause(room);
241	    buyer.buyTonic("late");
242	    buyer.sendInput(AHEAD);
243	    await sleep(150);
244	    room.stepWorldTicks(1);
245	    room.resumeWorld();
246	    buyer.sendInput({ moveX: 0, moveY: 0 });
247	    expect(room.matchState.ships.find((ship) => ship.id === buyer.sessionId)!.dock).toBe(-1);
248	    await buyer.waitFor(() => buyer.tonicPurchaseAnswers("late").length === 1);
249	    expect(buyer.tonicPurchaseAnswers("late")[0]).toEqual({ requestId: "late", outcome: "refused", reason: "not-at-dock", replayed: false });
250	    // At sea: refused again; a retry of the refused id replays it even back at the dock.
251	    expect(await buy(buyer)).toMatchObject({ outcome: "refused", reason: "not-at-dock" });
252	    await moor(buyer);
253	    expect(await buy(buyer, "late")).toMatchObject({ outcome: "refused", reason: "not-at-dock", replayed: true });
254	    expect(goldOf(room, buyer.sessionId)).toBe(START - PRICE);
255	    expect(room.ledgerState.goldSpent).toBe(PRICE);
256	  }, 30_000);
257	
258	  it("is no safe zone: a ship moored at the shop can be grappled, and a purchase in the duel is refused at no cost", async ({ onTestFinished }) => {
259	    const track = tracker(onTestFinished);
260	    const dock = dockFor("moon");
261	    // The attacker waits four tiles out from the dock, facing it.
262	    const out = [[1, 0], [-1, 0], [0, 1], [0, -1]].map(([dx, dy]) => ({ tileX: dock.tileX + dx! * 4, tileY: dock.tileY + dy! * 4, heading: dx === 1 ? WEST : dx === -1 ? EAST : dy === 1 ? NORTH : 16 }));
263	    const attackerSeat = out.find((seat) => isNavigable(seaMap, seat.tileX, seat.tileY) && openWater(seat, { ...dock, heading: 0 }))!;
264	    const [attacker, shopper] = (await playersAt(endpoint, [attackerSeat, ROW], track, { clients: [{}, { autoReady: false }] })) as [HeadlessClient, HeadlessClient];
265	    const room = roomOf(attacker);
266	    await moor(shopper, dock);
267	    await attacker.placeShip(endpoint, attackerSeat);
268	    attacker.tapGrapple();
269	    await shopper.waitFor(() => shopper.status()?.mode === "duel", 5000);
270	    // Still at the dock, but reserved for the duel: the ledger refuses it.
271	    expect(shopper.ship()?.dock).toBe(dock.id);
272	    expect(await buy(shopper, "fight")).toEqual({ requestId: "fight", outcome: "refused", reason: "player-in-duel", replayed: false });
273	    expect(goldOf(room, shopper.sessionId)).toBe(START);
274	    expect(tonicsOf(room, shopper.sessionId)).toBe(0);
275	    // It never readies, loses by forfeit and waits out of the world to respawn, its ship still at the dock: no shop there.
276	    await shopper.waitFor(() => shopper.status()?.mode === "respawning", 10_000);
277	    expect(room.matchState.ships.find((ship) => ship.id === shopper.sessionId)!.dock).toBe(dock.id);
278	    // (The lost duel moved 20 % of its gold to the winner; the refusal moves nothing.)
279	    const left = goldOf(room, shopper.sessionId);
280	    expect(left).toBe(START - START / 5);
281	    expect(await buy(shopper, "waiting")).toEqual({ requestId: "waiting", outcome: "refused", reason: "not-at-dock", replayed: false });
282	    expect(goldOf(room, shopper.sessionId)).toBe(left);
283	    expect(tonicsOf(room, shopper.sessionId)).toBe(0);
284	  }, 30_000);
285	
286	  it("keeps a tonic bought with id x and a rumor bought with id x apart: two purchases, and the match goes on", async ({ onTestFinished }) => {
287	    const track = tracker(onTestFinished);
288	    const [buyer] = (await playersAt(endpoint, [ROW], track)) as [HeadlessClient];
289	    const room = roomOf(buyer);
290	    await takeCrate(buyer, 3);
291	    await moor(buyer);
292	    expect(await buy(buyer, "x")).toMatchObject({ outcome: "bought" });
293	    // The shop's rumor is the journal's purchase: `buy-rumor`, the same flow, the same client id.
294	    await buyer.waitFor(() => buyer.rumorOffers().some((offer) => offer.type === "moon" && offer.offer === "available"));
295	    buyer.buyRumor("moon", "x");
296	    await buyer.waitFor(() => buyer.rumorAnswers("x").length === 1);
297	    expect(buyer.rumorAnswers("x")[0]).toMatchObject({ outcome: "bought", price: objectiveRules.rumorPrice, replayed: false });
298	    await sleep(200);
299	    expect(room.flowState.end).toBeNull();
300	    expect(goldOf(room, buyer.sessionId)).toBe(START + CRATE_GOLD - PRICE - objectiveRules.rumorPrice);
301	    expect(room.ledgerState.requests.map((request) => [request.requestId, request.kind])).toEqual([
302	      ["tonic:x", "purchase"],
303	      ["rumor:x", "purchase"],
304	    ]);
305	  }, 30_000);
306	});
307	
308	describe.concurrent("shop requests at the edges (§11, §16)", () => {
309	  it("answers tonic purchases and drinks still waiting when the match ends not-in-play, charging nothing", async ({ onTestFinished }) => {
310	    const track = tracker(onTestFinished);
311	    const [player] = (await playersAt(endpoint, [ROW], track)) as [HeadlessClient];
312	    const room = roomOf(player);
313	    await moor(player);
314	    await pause(room);
315	    player.buyTonic("end1");
316	    player.useTonic("end2");
317	    await until(() => room.pendingShop(player.sessionId) === 2, 2000, "both requests waiting");
318	    room.injectFault();
319	    room.stepWorldTicks(1);
320	    room.resumeWorld();
321	    await player.waitFor(() => player.tonicPurchaseAnswers("end1").length === 1 && player.tonicUseAnswers("end2").length === 1, 2000);
322	    expect(player.tonicPurchaseAnswers("end1")[0]).toEqual({ requestId: "end1", outcome: "refused", reason: "not-in-play", replayed: false });
323	    expect(player.tonicUseAnswers("end2")[0]).toEqual({ requestId: "end2", outcome: "refused", reason: "not-in-play", replayed: false });
324	    expect(room.pendingShop(player.sessionId)).toBe(0);
325	    expect(goldOf(room, player.sessionId)).toBe(START);
326	    // After the end, a new request is refused at once, a purchase or a drink.
327	    expect(await buy(player, "after")).toMatchObject({ outcome: "refused", reason: "not-in-play" });
328	    expect(await drink(player, "after")).toMatchObject({ outcome: "refused", reason: "not-in-play" });
329	  }, 30_000);
330	
331	  it("refuses a third waiting request of a kind busy, drops malformed ones and those past 8 a second, and answers not-in-play in the lobby", async ({ onTestFinished }) => {
332	    const track = tracker(onTestFinished);
333	    const host = await HeadlessClient.create(endpoint);
334	    track(host);
335	    // In the lobby: refused, not kept.
336	    expect(await buy(host, "early")).toEqual({ requestId: "early", outcome: "refused", reason: "not-in-play", replayed: false });
337	    const bench = await startThroughLobby(endpoint, [host]);
338	    track(bench!);
339	    const room = roomOf(host);
340	    // The rate cap counts per second of the room's own clock: wait out a window by its frames, not the wall clock.
341	    const nextWindow = async () => {
342	      const from = room.matchState.frame;
343	      await until(() => room.matchState.frame > from + 60, 5000, "a new rate window");
344	    };
345	    await moor(host);
346	    await nextWindow();
347	    // Three purchases and three drinks between two ticks: two of each wait, the third of each is busy at once.
348	    await pause(room);
349	    for (const id of ["p1", "p2", "p3"]) host.buyTonic(id);
350	    for (const id of ["d1", "d2", "d3"]) host.useTonic(id);
351	    await host.waitFor(() => host.tonicPurchaseAnswers("p3").length === 1 && host.tonicUseAnswers("d3").length === 1, 2000);
352	    expect(host.tonicPurchaseAnswers("p3")[0]).toEqual({ requestId: "p3", outcome: "refused", reason: "busy", replayed: false });
353	    expect(host.tonicUseAnswers("d3")[0]).toEqual({ requestId: "d3", outcome: "refused", reason: "busy", replayed: false });
354	    expect(room.pendingShop(host.sessionId)).toBe(4);
355	    room.stepWorldTicks(2);
356	    room.resumeWorld();
