1	import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
2	import { seaMap } from "@pirate-sea-race/content";
3	import { Buttons, WORLD_HOLD_GRACE_FRAMES } from "@pirate-sea-race/protocol";
4	import { startGameServer, type MatchRoom, type RunningGameServer } from "@pirate-sea-race/server";
5	import { fruitRules } from "@pirate-sea-race/simulation/fruits";
6	import { findPlayer, objectiveRules } from "@pirate-sea-race/simulation/objectives";
7	import { sleep, type HeadlessClient, type Movement } from "@pirate-sea-race/test-tools";
8	import { tuned } from "./rubbingsSetup.js";
9	import { dockFor, EAST, HOLD_E, HUB_X, OPEN_ROW, playersAt, roomOf, tracker, until, type Seat } from "./seaDuelSetup.js";
10	
11	/**
12	 * Holds through short network gaps (the operator's playtest bug, §12, `docs/architecture.md`): a player holds E (or F)
13	 * as a browser does, resending the held input every 100 ms, while the headless client's transport withholds its input
14	 * messages for a while (`stallInput`), as a stalled network would. A world hold button survives gaps of up to 750 ms
15	 * (`WORLD_HOLD_GRACE_FRAMES`) in the room's hold reads only; movement keeps the 250 ms lapse, and a moored ship keeps its
16	 * mooring. The collection is the real six seconds here (the rules' own `collectTicks`); eating is three.
17	 */
18	let server: RunningGameServer;
19	let endpoint: string;
20	
21	beforeAll(async () => {
22	  server = await startGameServer({
23	    port: 0,
24	    host: "127.0.0.1",
