920	+import type { TonicPurchaseMessage, TonicPurchaseRefusalName, TonicUsedMessage, TonicUseRefusalName } from "@pirate-sea-race/protocol";
921	+import type { PurchaseResult, ShopItem, TonicResult } from "@pirate-sea-race/simulation/objectives";
922	+
923	+/**
924	+ * The dockside shop in the room (§11, §16): the book of each player's tonic purchases and drinks by request id, and how
925	+ * the ledger's answers become the answers players get. Plain data and small classes, no Colyseus: `MatchRoom` owns the
926	+ * timing.
927	+ */
928	+
929	+/**
930	+ * The ledger's request id for a client's purchase: the ledger keeps one id space per player for both items, so the
931	+ * room namespaces it by item. A client id reused for a tonic and a rumor is then two purchases, never a `duplicate`.
932	+ */
933	+export const ledgerRequestId = (item: ShopItem, clientId: string): string => `${item}:${clientId}`;
934	+
935	+/** A request waiting for its world tick. */
936	+export interface PendingShopRequest {
937	+  readonly requestId: string;
938	+}
939	+
940	+export type TonicPurchaseDecision = { readonly outcome: "bought"; readonly price: number; readonly tonics: number } | { readonly outcome: "refused"; readonly reason: TonicPurchaseRefusalName };
941	+export type TonicUseDecision = { readonly outcome: "active"; readonly endTick: number } | { readonly outcome: "refused"; readonly reason: TonicUseRefusalName };
942	+
943	+/** At most this many requests of one kind wait per player; more are refused `busy` and kept nowhere. */
944	+export const MAX_PENDING_SHOP_REQUESTS = 2;
945	+/** The refusals of one kind kept per player for replays (the oldest goes first), as the ledger keeps its own. */
946	+export const KEPT_SHOP_REFUSALS = 16;
947	+
948	+interface PlayerRequests<D> {
949	+  readonly pending: PendingShopRequest[];
950	+  /** Every applied request id, never evicted (bounded by gold, or by the tonics bought). */
951	+  readonly applied: Map<string, D>;
952	+  /** The last `KEPT_SHOP_REFUSALS` refused request ids, oldest first. */
953	+  readonly refused: Map<string, D>;
954	+}
955	+
956	+/**
957	+ * One kind of shop request (tonic purchases, or drinks), per player, by the client's request id (§16): an id already
958	+ * decided is answered from `decided` first; one still pending is merged into it (one answer); at most
959	+ * `MAX_PENDING_SHOP_REQUESTS` wait per player, and the room takes one per player per world tick, oldest first.
960	+ */
961	+export class ShopBook<D extends { readonly outcome: string }> {
962	+  private readonly books = new Map<string, PlayerRequests<D>>();
963	+
964	+  private bookOf(playerId: string): PlayerRequests<D> {
965	+    let book = this.books.get(playerId);
966	+    if (book === undefined) {
967	+      book = { pending: [], applied: new Map(), refused: new Map() };
968	+      this.books.set(playerId, book);
969	+    }
970	+    return book;
971	+  }
972	+
973	+  /** The room's earlier decision on this (player, request id), if it kept one. */
974	+  decided(playerId: string, requestId: string): D | undefined {
975	+    const book = this.books.get(playerId);
976	+    return book?.applied.get(requestId) ?? book?.refused.get(requestId);
977	+  }
978	+
979	+  /** A request arrives whose id this player has no decision for (the caller replays those first). */
980	+  arrive(playerId: string, requestId: string): "merged" | "busy" | "queued" {
981	+    const book = this.bookOf(playerId);
982	+    if (book.pending.some((each) => each.requestId === requestId)) return "merged";
983	+    if (book.pending.length >= MAX_PENDING_SHOP_REQUESTS) return "busy";
984	+    book.pending.push({ requestId });
985	+    return "queued";
986	+  }
987	+
988	+  /** The players with a request waiting. */
989	+  waiting(): string[] {
990	+    return [...this.books].filter(([, book]) => book.pending.length > 0).map(([id]) => id);
991	+  }
992	+
993	+  /** This player's oldest waiting request, taken off the queue. */
994	+  take(playerId: string): PendingShopRequest | undefined {
995	+    return this.books.get(playerId)?.pending.shift();
996	+  }
997	+
998	+  pendingCount(playerId: string): number {
999	+    return this.books.get(playerId)?.pending.length ?? 0;
1000	+  }
1001	+
1002	+  /** Every request still waiting, by player, taken off their queues (the match has ended). */
1003	+  drain(): { readonly playerId: string; readonly request: PendingShopRequest }[] {
1004	+    return [...this.books].flatMap(([playerId, book]) => book.pending.splice(0).map((request) => ({ playerId, request })));
1005	+  }
1006	+
1007	+  /** Keeps a decision for replays: every applied one, and the player's last refusals. */
1008	+  decide(playerId: string, requestId: string, decision: D, applied: boolean): void {
1009	+    const book = this.bookOf(playerId);
1010	+    if (applied) {
1011	+      book.applied.set(requestId, decision);
1012	+      return;
1013	+    }
1014	+    book.refused.set(requestId, decision);
1015	+    if (book.refused.size > KEPT_SHOP_REFUSALS) book.refused.delete(book.refused.keys().next().value!);
1016	+  }
1017	+
1018	+  forget(playerId: string): void {
1019	+    this.books.delete(playerId);
1020	+  }
1021	+}
1022	+
1023	+/** The ledger's decided purchase refusals: the ones it keeps, so a retry is refused the same way. */
1024	+const PURCHASE_REFUSALS: readonly string[] = ["player-in-duel", "player-disconnected", "tonic-limit", "insufficient-gold"];
1025	+
1026	+/**
1027	+ * A tonic purchase as the ledger decided it (`purchase` under `ledgerRequestId("tonic", id)`): bought, with the price and
1028	+ * the tonics now carried, or refused with the ledger's decided refusal. The room asks only for a player in the match
1029	+ * with a fresh namespaced id, so any other answer (malformed, stale, an unknown or departed player, a `duplicate`) is a
1030	+ * broken invariant: it throws, and the world tick faults (§12).
1031	+ */
1032	+export function tonicPurchaseOf(result: PurchaseResult): TonicPurchaseDecision {
1033	+  if (result.ok) return { outcome: "bought", price: result.purchase!.price, tonics: result.purchase!.tonicsAfter };
1034	+  if (result.refusal !== null && PURCHASE_REFUSALS.includes(result.refusal.rejection)) return { outcome: "refused", reason: result.refusal.rejection as TonicPurchaseRefusalName };
1035	+  throw new Error(`the ledger did not decide a tonic purchase: ${result.rejection}`);
1036	+}
1037	+
1038	+/** The ledger's refusals of a drink that the players hear. */
1039	+const USE_REFUSALS: readonly string[] = ["tonic-active", "no-tonic", "not-at-sea", "grappled", "player-in-duel", "player-disconnected"];
1040	+
1041	+/**
1042	+ * A drink as the ledger decided it (`useTonic` on tick `tick`): active, its last boosted sailing step `tick + ticks`, or
1043	+ * refused with the ledger's reason. Any other refusal (malformed, stale, an unknown or departed player) is a broken
1044	+ * invariant, as above: it throws.
1045	+ */
1046	+export function tonicUseOf(result: TonicResult, tick: number, ticks: number): TonicUseDecision {
1047	+  if (result.ok) return { outcome: "active", endTick: tick + ticks };
1048	+  if (result.rejection !== null && USE_REFUSALS.includes(result.rejection)) return { outcome: "refused", reason: result.rejection as TonicUseRefusalName };
