1050	+}
1051	+
1052	+/** The answer to a tonic purchase request, as its player receives it; `replayed` when it answers an id already decided. */
1053	+export function tonicPurchaseMessage(requestId: string, decision: TonicPurchaseDecision, replayed: boolean): TonicPurchaseMessage {
1054	+  return decision.outcome === "bought"
1055	+    ? { requestId, outcome: "bought", price: decision.price, tonics: decision.tonics, replayed }
1056	+    : { requestId, outcome: "refused", reason: decision.reason, replayed };
1057	+}
1058	+
1059	+/** The answer to a drink request, as its player receives it. */
1060	+export function tonicUsedMessage(requestId: string, decision: TonicUseDecision, replayed: boolean): TonicUsedMessage {
1061	+  return decision.outcome === "active" ? { requestId, outcome: "active", endTick: decision.endTick, replayed } : { requestId, outcome: "refused", reason: decision.reason, replayed };
